from collections import deque
R,C=arr.shape
seen=set(); comps=[]
for r,c in zip(*np.where(arr==1)):
    if (r,c) in seen: continue
    q=[(r,c)]; seen.add((r,c)); cells=[]
    while q:
        p=q.pop(); cells.append(p)
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(p[0]+dr,p[1]+dc)
            if 0<=n[0]<R and 0<=n[1]<C and arr[n]==1 and n not in seen: seen.add(n);q.append(n)
    comps.append(cells)
[(len(x),(min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps]

# label ones components and zero regions
lab1=np.full((R,C),-1,int)
for i,cells in enumerate(comps):
  for p in cells: lab1[p]=i
lab0=np.full((R,C),-1,int); regions=[]
for r in range(R):
 for c in range(C):
  if arr[r,c]!=0 or lab0[r,c]>=0: continue
  q=[(r,c)]; lab0[r,c]=len(regions); cells=[]
  while q:
   p=q.pop();cells.append(p)
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    nr,nc=p[0]+dr,p[1]+dc
    if 0<=nr<R and 0<=nc<C and arr[nr,nc]==0 and lab0[nr,nc]<0:
      lab0[nr,nc]=len(regions);q.append((nr,nc))
  regions.append(cells)
for i,reg in enumerate(regions):
  bounded=not any(r in(0,R-1) or c in(0,C-1) for r,c in reg)
  adj=set(lab1[r+dr,c+dc] for r,c in reg for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<R and 0<=c+dc<C and lab1[r+dr,c+dc]>=0)
  if bounded: print(i,len(reg),(min(r for r,c in reg),max(r for r,c in reg),min(c for r,c in reg),max(c for r,c in reg)),adj)

# Each bounded zero component activates adjacent 1 components; color 8-neighbor zero band on either side of active component.
bounded_regions={i for i,reg in enumerate(regions) if not any(r in(0,R-1) or c in(0,C-1) for r,c in reg)}
active=set()
for i,reg in enumerate(regions):
 if i in bounded_regions:
  active.update(lab1[r+dr,c+dc] for r,c in reg for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<R and 0<=c+dc<C and lab1[r+dr,c+dc]>=0)
out=arr.copy()
for i in active:
 for r,c in comps[i]:
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    nr,nc=r+dr,c+dc
    if 0<=nr<R and 0<=nc<C and arr[nr,nc]==0:
     out[nr,nc]=3 if lab0[nr,nc] in bounded_regions else 2
print('active',active)
for row in out: print(' '.join(map(str,row)))
